--
-- Name: bs_game_player_stat; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bs_game_player_stat (
    id bigint NOT NULL,
    game_id bigint,
    team_id bigint,
    player_id bigint,
    batting_order integer,
    list_order integer,
    pitcher_order integer,
    "position" character varying(255),
    number character varying(255),
    bat_hand character varying(255),
    throw_hand character varying(255),
    pa integer,
    ab integer,
    r integer,
    h integer,
    e integer,
    bb_hp integer,
    sb integer,
    so integer,
    rbi integer,
    doubles integer,
    triples integer,
    hr integer,
    inside_park_hr integer,
    gdp integer,
    sh integer,
    sf integer,
    bb integer,
    ibb integer,
    hbp integer,
    cs integer,
    is_pitcher integer,
    ip double precision,
    earnedr integer,
    er integer,
    pitchh integer,
    pitch_bb_hp integer,
    pitch_so integer,
    pitch_hr integer,
    gs integer,
    svo integer,
    cg integer,
    pg integer,
    w integer,
    l integer,
    sv integer,
    hld integer,
    pitch_pa integer,
    np integer,
    pitch_bb integer,
    pitch_ibb integer,
    pitch_hbp integer,
    wp integer,
    bk integer,
    pitchr integer,
    go integer,
    fo integer,
    tc integer,
    po integer,
    a integer,
    created_by bigint,
    created_at timestamp with time zone,
    updated_by bigint,
    updated_at timestamp with time zone,
    deleted_by bigint,
    deleted_at timestamp with time zone,
    fielding_gs integer,
    def_inn double precision,
    dp integer,
    so_swing integer DEFAULT 0,
    so_looking integer DEFAULT 0,
    tenant_id bigint DEFAULT 1 NOT NULL,
    pb integer,
    catcher_sb integer,
    catcher_cs integer,
    pitch_bf integer,
    pitch_inside_park_hr integer DEFAULT 0,
    pitch_ab integer,
    bbhp integer,
    earned_r integer,
    pitch_h integer,
    pitch_bbhp integer,
    pitch_r integer
);


ALTER TABLE public.bs_game_player_stat OWNER TO postgres;

