--

CREATE TABLE public.bs_highlight_moment (
    id bigint NOT NULL,
    subject_type character varying(255) DEFAULT 'player'::character varying,
    subject_id bigint,
    history_event_id bigint,
    display_key character varying(255) DEFAULT 'player_profile'::character varying,
    tenant_id bigint,
    title character varying(200),
    description character varying(2000),
    media_type character varying(255) DEFAULT 'image'::character varying,
    media_source character varying(255) DEFAULT 'upload'::character varying,
    media_url character varying(2000),
    cover_url character varying(2000),
    happened_at character varying(255),
    sort_weight bigint DEFAULT 0,
    pinned bigint DEFAULT 0,
    status character varying(255) DEFAULT 'published'::character varying,
    created_by bigint,
    created_at timestamp with time zone,
    updated_by bigint,
    updated_at timestamp with time zone,
    deleted_by bigint,
    deleted_at timestamp with time zone
);


ALTER TABLE public.bs_highlight_moment OWNER TO postgres;

