    id bigint NOT NULL,
    rule_kind character varying(8) NOT NULL,
    scope_type character varying(32) DEFAULT 'GLOBAL'::character varying NOT NULL,
    role_id bigint,
    api_pattern character varying(512),
    cidr_or_ip character varying(128) NOT NULL,
    priority bigint DEFAULT 0,
    enabled smallint DEFAULT 1,
