    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    created_by bigint,
    updated_by bigint,
    tenant_id bigint DEFAULT 1 NOT NULL,
    CONSTRAINT chk_sys_ip_access_rule_kind CHECK (((rule_kind)::text = ANY (ARRAY[('ALLOW'::character varying)::text, ('DENY'::character varying)::text]))),
    CONSTRAINT chk_sys_ip_access_rule_scope CHECK (((scope_type)::text = ANY (ARRAY[('GLOBAL'::character varying)::text, ('ROLE'::character varying)::text, ('API_PREFIX'::character varying)::text])))
);


